import 'package:add_to_cart_animation/add_to_cart_animation.dart';
import 'package:flutter/material.dart';

void main() => runApp(const MyApp());

class MyApp extends StatelessWidget {
  const MyApp({super.key});
  @override
  Widget build(BuildContext context) => MaterialApp(home: const DemoPage());
}

class DemoPage extends StatefulWidget {
  const DemoPage({super.key});
  @override
  State<DemoPage> createState() => _DemoPageState();
}

class _DemoPageState extends State<DemoPage> {
  final GlobalKey<CartIconKey> cartKey = GlobalKey<CartIconKey>();
  late Function(GlobalKey) runAddToCart;
  int items = 0;

  @override
  Widget build(BuildContext context) => AddToCartAnimation(
        cartKey: cartKey,
        createAddToCartAnimation: (run) => runAddToCart = run,
        child: Scaffold(
          appBar: AppBar(
            title: const Text('Demo'),
            actions: [AddToCartIcon(key: cartKey)],
          ),
          body: ListTile(
            leading: Container(
              key: GlobalKey(),
              width: 60,
              height: 60,
              child: const Icon(Icons.shopping_bag),
            ),
            title: const Text('Item'),
            onTap: () async {
              await runAddToCart(GlobalKey());
              await cartKey.currentState!.runCartAnimation((++items).toString());
            },
          ),
        ),
      );
}
